<?php
 namespace Pterodactyl\Services\Servers; use Pterodactyl\Models\User; use Pterodactyl\Models\Server; use Pterodactyl\Services\Dezerx\Demo; use Pterodactyl\Services\Dezerx\Staff\StaffAccess; class GetUserPermissionsService { public function handle(Server $server, User $user): array { if (Demo::is($user)) { return Demo::PERMISSIONS; } if ($user->root_admin || $user->id === $server->owner_id) { $permissions = ['*']; if ($user->root_admin) { $permissions[] = 'admin.websocket.errors'; $permissions[] = 'admin.websocket.install'; $permissions[] = 'admin.websocket.transfer'; } return $permissions; } $subuserPermissions = $server->subusers()->where('user_id', $user->id)->first(); if ($subuserPermissions === null || !StaffAccess::usable($subuserPermissions)) { return []; } return $subuserPermissions->permissions ?? []; } } 